mapper.select:
select fined.id as id, fined.case_id as caseId, fined.case_no as caseNo, fined.case_type as caseType, fined.gradation_state as gradationState, fined.case_state as caseState, fined.case_title as caseTitle, fined.case_name as caseName, fined.org_name as orgName, fined.org_id as orgId , fined.is_fined as isFined, fined.fined_type as finedType, fined.fined_money as finedMoney, fined.fined_by_id as finedById, fined.fined_by as finedBy, fined.fined_time as finedTime ,fined.fined_type_name as finedTypeName from case_center_info_fined fined left join case_center_info cci on fined.case_id = cci.case_id where fined.is_fined =0
and fined.case_name like CONCAT('%',#{caseName,jdbcType=VARCHAR},'%')
and fined.case_no like CONCAT('%',#{caseNo,jdbcType=VARCHAR},'%')
and fined.case_title like CONCAT('%',#{caseTitle,jdbcType=VARCHAR},'%')
and fined.fined_type = #{finedType,jdbcType=INTEGER}
and fined.case_type = #{caseType,jdbcType=INTEGER}
and cci.is_test_case = #{isTestcase,jdbcType=INTEGER}
and cci.is_test_case = 0
and cci.is_test_case = 1
and cci.delete_flag !=1 order by fined.fined_time desc limit #{pageIndex} , #{pageSize}

select count(1) from case_center_info_fined fined left join case_center_info cci on fined.case_id = cci.case_id where fined.is_fined =0
and fined.case_name like CONCAT('%',#{caseName,jdbcType=VARCHAR},'%')
and fined.case_no like CONCAT('%',#{caseNo,jdbcType=VARCHAR},'%')
and fined.case_title like CONCAT('%',#{caseTitle,jdbcType=VARCHAR},'%')
and fined.fined_type = #{finedType,jdbcType=INTEGER}
and fined.case_type = #{caseType,jdbcType=INTEGER}
and cci.is_test_case = #{isTestcase,jdbcType=INTEGER}
and cci.is_test_case = 0
and cci.is_test_case = 1
and cci.delete_flag !=1
